class RangeSliderHandle extends GameObject {
  
  private float _min = 0f;
  private float _max = 1f;
  private float _value = 0.5f;
  private float _diameter = 9f;
  private int _c = color(0xFFFFFFFF);
  private boolean _dragged = false;
  
  RangeSliderHandle(float value, float minValue, float maxValue, int colorValue) {
    super();
    this._value = value;
    this._min = minValue;
    this._max = maxValue;
    this._diameter = 9f;
    this._c = colorValue;
    this._dragged = false;
  }
  
  public void setDiameter(float value) {
    this._diameter = value;
  }
  
  public void setValue(float value) {
    this._value = value;
  }
  
  public void setRange(float minValue, float maxValue) {
    this._min = minValue;
    this._max = maxValue;
  }
  
  public void setMax(float max) {
    _max = max;
    if (_value > _max) {
      _value = _max; 
    }
    if (_min > _max) {
      _min = _max; 
    }
  }
  
  public void drag(boolean drag) {
     this._dragged = drag;
  }
  
  public float getDiameter() {
    return this._diameter;
  }
  
  public float getValue() {
    return this._value;
  }
  
  public int getColor() {
    return this._c;
  }
  
  public float getMinValue() {
    return this._min;
  }
  
  public float getMaxValue() {
    return this._max;
  }
  
  public Tuple2<Float, Float> getRange() {
    return new Tuple2<Float, Float>(this._min, this._max);
  }
  
  public void draw(PGraphics drawTarget) {
    if (this._dragged) {
      drawTarget.pushMatrix();
      drawTarget.pushStyle();
      drawTarget.noStroke();
      drawTarget.fill(red(this._c), green(this._c), blue(this._c), 128);
      drawTarget.ellipseMode(CENTER);
      drawTarget.circle(super._pos.x + this._diameter / 2f, super._pos.y + this._diameter / 2f, this._diameter * 2f);
      drawTarget.popStyle();
      drawTarget.popMatrix();   
    }

    drawTarget.pushMatrix();
    drawTarget.pushStyle();
    drawTarget.stroke(255);
    drawTarget.strokeWeight(this._diameter * 0.09f);
    drawTarget.fill(this._c);
    drawTarget.circle(super._pos.x, super._pos.y, this._diameter);
    drawTarget.popStyle();
    drawTarget.popMatrix();
  }
  
  public boolean inside(float tempX, float tempY) {  
    float r = this._diameter / 2.0f;
    
    float x = super._pos.x + r;
    float y = super._pos.y + r;
    
    return (tempX - x) * (tempX - x) + (tempY - y) * (tempY - y) < r * r;
  }
  
  public void onDrag(float mouseXPos, float sliderStart, float sliderEnd) {
    this._dragged = true;
    this._value = map(mouseXPos, sliderStart, sliderEnd, this._min, this._max);
    if (this._value > this._max) {
      this._value = this._max;
    }
    else if (this._value < this._min) {
       this._value = this._min;
    }
  }
}
class SaperBoard extends GameObject {
  
  private int _cellWidth, _cellHeight;
  private int _columns, _rows;
  
  private int _bombsNumber = 10;
  
  private ArrayList<SaperCell> _cells = new ArrayList<SaperCell>();
  
  private boolean _gameEnded = false;
  private boolean _lost = false;
  
  public SaperBoard(int cellWidth, int cellHeight, int columns, int rows) {
    _cellWidth = cellWidth;
    _cellHeight = cellHeight;
    _columns = columns;
    _rows = rows;
  }
  
  public void draw(PGraphics drawTarget) {
    for (int i = 0; i < _cells.size(); i++) {
     _cells.get(i).draw(drawTarget);
    }
  }
  
  public void mouseClicked() {    
    if (!_gameEnded) {
      for (int i = 0; i < _cells.size(); i++) {
        _cells.get(i).mouseClicked();
      }
    }
  }
  
  public void setPosition(float x, float y) {
    this.setPosition(new PVector(x, y)); 
  }
  
  public void setPosition(PVector pos) {
    PVector lpos = getPosition();
    super.setPosition(pos);
    PVector diff = new PVector(pos.x - lpos.x, pos.y - lpos.y);
    
    for (int i = 0; i < _cells.size(); i++) {
      SaperCell cell = _cells.get(i);
      PVector cellPos = cell.getPosition();
      cell.setPosition(cellPos.x + diff.x, cellPos.y + diff.y);
    }
  }
  
  public void setRowsNumber(int num) {
    _rows = num;
    _bombsNumber = min(_bombsNumber, _rows * _columns);
  }
  
  public void setColumnsNumber(int num) {
    _columns = num;
    _bombsNumber = min(_bombsNumber, _rows * _columns);
  }
  
  public boolean checkBoard() {
    if (_lost) return false;
    
    int goodFlags = 0;
    boolean allNotBombsEnabled = true;
    for (int i = 0; i < _cells.size(); i++) {
      SaperCell cell = _cells.get(i);
      if (cell.isFlaged() && cell.isBomb()) {
        goodFlags++;
      }
      if (!cell.isBomb() && !cell.isEnabled()) {
         allNotBombsEnabled = false;
      }
    }
    return goodFlags == _bombsNumber || allNotBombsEnabled;
  }
  
  public boolean isGameEnded() {
    return _gameEnded; 
  }
  
  public void generate(int bombsNumber) {
    _gameEnded = false;
    _bombsNumber = bombsNumber;
    
    float startX = (width / 2f) - (_columns / 2f) * _cellWidth + _cellWidth / 2f;
    float startY = (height / 2f) - (_rows / 2f) * _cellHeight + _cellHeight / 2f;
    
    ArrayList<Integer> emptyCells = new ArrayList<Integer>();
    for (int i = 0; i < _rows * _columns; i++) {
       emptyCells.add(i);
    }
    
    ArrayList<Integer> bombCells = new ArrayList<Integer>();
    for (int i = 0; i < _bombsNumber; i++) {
      int cellNum = (int)random(0, emptyCells.size());
      bombCells.add(emptyCells.get(cellNum));
      emptyCells.remove(emptyCells.get(cellNum));
    }
    
    _cells.clear();
    for (int idX = 0; idX < _columns; idX++) {
      for (int idY = 0; idY < _rows; idY++) {
        float x = startX + idX * _cellWidth;
        float y = startY + idY * _cellHeight;
        
        final int currIdX = idX;
        final int currIdY = idY;
        
        SaperCell cell = null;
        if (bombCells.contains(idX * _rows + idY)) {
          cell = new SaperCell(x, y, _cellWidth, _cellHeight);
          
          cell.addAction(() -> {
            if (mouseButton == LEFT) {
              _gameEnded = true;
              _lost = true;
            }
          });
        }
        else {
          int bombsNum = 0;
          for (int iX = max(idX - 1, 0); iX <= min(idX + 1, _columns - 1); iX++) {
            for (int iY = max(idY - 1, 0); iY <= min(idY + 1, _rows - 1); iY++) {
               if (iX != idX || iY != idY) {
                 if (bombCells.contains(iX * _rows + iY)) {
                   bombsNum++;
                 }
               }
            }
          }
          
          cell = new SaperCell(x, y, _cellWidth, _cellHeight, bombsNum);
          
          if (cell.isEmpty()) {
            cell.addAction(() -> {
              if (mouseButton == LEFT) {
                for (int iX = max(currIdX - 1, 0); iX <= min(currIdX + 1, _columns - 1); iX++) {
                  for (int iY = max(currIdY - 1, 0); iY <= min(currIdY + 1, _rows - 1); iY++) {
                     if (iX != currIdX || iY != currIdY) {
                       SaperCell nearCell = _cells.get(iX * _rows + iY);
                       if (!nearCell.isFlaged()) {
                         int lastMB = mouseButton;
                         mouseButton = LEFT;
                         if (nearCell.isEmpty() && !nearCell.isEnabled()) {
                            nearCell.Invoke();
                         }
                         else if (!nearCell.isEmpty() && !nearCell.isEnabled()) {
                            nearCell.Invoke();
                         }
                         mouseButton = lastMB;
                       }
                     }
                  }
                }
              }
            });
          }
        }
        cell.addAction(() -> {
          if (checkBoard()) {
            _gameEnded = true;
          }
          
          if (_gameEnded) {
            for (int iX = 0; iX < _columns; iX++) {
              for (int iY = 0; iY < _rows; iY++) {
                if (iX != currIdX || iY != currIdY) {
                  _cells.get(iX * _rows + iY).enable(true);
                }
              }
            } 
          }
        });
        
        _cells.add(cell);
      }
    }
  }
  
  public JSONObject getJSONObject() {
    JSONObject boardJson = new JSONObject();
    
    boardJson.setInt("Rows", _rows);
    boardJson.setInt("Columns", _columns);
    boardJson.setInt("Bombs", _bombsNumber);
    
    JSONArray cellsArray = new JSONArray();
    for (int i = 0; i < _rows * _columns; i++) {
      cellsArray.append(_cells.get(i).getJSONObject()); 
    }
    boardJson.setJSONArray("Cells", cellsArray);
    
    return boardJson;
  }
  
  public void loadJSONObject(JSONObject boardJson) {
     _rows = boardJson.getInt("Rows");
     _columns = boardJson.getInt("Columns");
     _bombsNumber = boardJson.getInt("Bombs");
     
     _cells.clear();
     float startX = (width / 2f) - (_columns / 2f) * _cellWidth + _cellWidth / 2f;
     float startY = (height / 2f) - (_rows / 2f) * _cellHeight + _cellHeight / 2f;
     
     JSONArray cellsArray = boardJson.getJSONArray("Cells");
     for (int idX = 0; idX < _columns; idX++) {
       for (int idY = 0; idY < _rows; idY++) {
         float x = startX + idX * _cellWidth;
         float y = startY + idY * _cellHeight;
         
         SaperCell cell = new SaperCell(x, y, _cellWidth, _cellHeight, cellsArray.getJSONObject(idX * _rows + idY));
         
         if (cell.isBomb()) {
           cell.addAction(() -> {
            if (mouseButton == LEFT) {
              _gameEnded = true;
            }
          }); 
         }
         else if (cell.isEmpty()) {
           final int currIdX = idX;
           final int currIdY = idY;
           
           cell.addAction(() -> {
              if (mouseButton == LEFT) {
                for (int iX = max(currIdX - 1, 0); iX <= min(currIdX + 1, _columns - 1); iX++) {
                  for (int iY = max(currIdY - 1, 0); iY <= min(currIdY + 1, _rows - 1); iY++) {
                     if (iX != currIdX || iY != currIdY) {
                       SaperCell nearCell = _cells.get(iX * _rows + iY);
                       if (!nearCell.isFlaged()) {
                         int lastMB = mouseButton;
                         mouseButton = LEFT;
                         if (nearCell.isEmpty() && !nearCell.isEnabled()) {
                            nearCell.Invoke();
                         }
                         else if (!nearCell.isEmpty() && !nearCell.isEnabled()) {
                            nearCell.Invoke();
                         }
                         mouseButton = lastMB;
                       }
                     }
                  }
                }
              }
            });
         }
         
         cell.addAction(() -> {
          if (checkBoard()) {
            _gameEnded = true;
          }
        });
         
         _cells.add(cell);
       }
     }
  }
}
class SaperCell extends GameObject {
  private int _w, _h;
  private boolean _isBomb;
  private boolean _flaged;
  private int _num;
  private Text _text;
  private Button _button;
  
  private QuickObject _flag;
  private QuickObject _bomb;
  
  public SaperCell(float x, float y, int w, int h, JSONObject cellJson) {
    this(x, y, w, h, cellJson.getBoolean("IsBomb"), cellJson.getInt("Num"));
    _flaged = cellJson.getBoolean("IsFlaged");
    enable(cellJson.getBoolean("IsEnabled"));
  }
  
  public SaperCell(float x, float y, int w, int h) {
    this(x, y, w, h, true, 0);
  }
  
  public SaperCell(float x, float y, int w, int h, int num) {
    this(x, y, w, h, false, num);
  }
  
  private SaperCell(float x, float y, int w, int h, boolean isBomb, int num) {
    super(x, y);
    enable(false);
    
    _isBomb = isBomb;
    _num = num;
    
    _w = w;
    _h = h;
    
    _button = new Button(x, y, w, h);
    _button.setColor(color(225));
    _button.setHasStroke(true);
    _button.setStrokeColor(color(0));
    _button.addAction(() -> {
      if (mouseButton == LEFT) {
        enable(true);
      }
      else if (mouseButton == RIGHT) {
        _flaged = !_flaged;
      }
    });
    
    _flag = new QuickObject(x, y, (ref, drawTarget) -> {
      drawTarget.pushMatrix();
      drawTarget.pushStyle();
      
      PVector pos = ref.getPosition();
      float scale = 15f;
      drawTarget.fill(255, 0, 0);
      drawTarget.noStroke();
      
      drawTarget.translate(pos.x, pos.y - 5);
      drawTarget.pushMatrix();
      drawTarget.rotate(radians(90));
      drawTarget.triangle(-scale / 2f, scale / 2f, 0, -scale / 2f, scale / 2f, scale / 2f);
      drawTarget.popMatrix();
      
      drawTarget.fill(0);
      drawTarget.stroke(0);
      drawTarget.strokeWeight(2);
      drawTarget.line(-7.5f, -7.5f, -7.5f, 20);
      
      drawTarget.popStyle();
      drawTarget.popMatrix();
    });
    
    if (_isBomb) {
      _bomb = new QuickObject(x, y, (ref, drawTarget) -> {
        drawTarget.pushMatrix();
        drawTarget.pushStyle();
        
        PVector pos = ref.getPosition();
        drawTarget.translate(pos.x, pos.y);
        
        drawTarget.stroke(230, 153, 0);
        drawTarget.strokeWeight(4);
        drawTarget.line(0, 0, 0, -12);
        
        drawTarget.fill(0);
        drawTarget.noStroke();
        drawTarget.rectMode(CENTER);
        drawTarget.rect(0, -1.25f, 10, 10);
        drawTarget.circle(0, 5, 20);
        
        drawTarget.popStyle();
        drawTarget.popMatrix();
      });
    }
    else if (_num != 0) {
      _text = new Text(x, y, "" + _num);
    }
  }
  
  public void draw(PGraphics drawTarget) {
    drawTarget.pushMatrix();
    drawTarget.pushStyle();
    
    if (isEnabled()) {
      drawTarget.fill(160);
      drawTarget.rectMode(CENTER);
      PVector pos = getPosition();
      drawTarget.rect(pos.x, pos.y, _w, _h);
      
      if (_isBomb) {
        _bomb.draw(drawTarget); 
      }
      else if (_num != 0) {
        _text.draw(drawTarget);
      }
    }
    else {
      _button.draw(drawTarget);
      
      if (_flaged) {
        _flag.draw(drawTarget); 
      }
    }
    
    drawTarget.popStyle();
    drawTarget.popMatrix();
  }
  
  public void mouseClicked() {
    if (!isEnabled()) {
      if (!_flaged || mouseButton == RIGHT) {
        _button.mouseClicked(); 
      }
    }
  }
  
  public void addAction(ButtonAction action) {
    _button.addAction(action); 
  }
  
  public void Invoke() {
    int lastMB = mouseButton;
    mouseButton = LEFT;
    _button.Invoke();
    mouseButton = lastMB;
  }
  
  public boolean isBomb() {
    return _isBomb;
  }
  
  public boolean isEmpty() {
    return _num == 0;
  }
  
  public boolean isFlaged() {
    return _flaged && !isEnabled(); 
  }
  
  public void setPosition(float x, float y) {
    this.setPosition(new PVector(x, y));
  }
  
  public void setPosition(PVector pos) {
    super.setPosition(pos);
    _flag.setPosition(pos);
    if (_isBomb) {
      _bomb.setPosition(pos); 
    }
    else if (_num != 0) {
      _text.setPosition(pos); 
    }
  }
  
  public JSONObject getJSONObject() {
    JSONObject cellJson = new JSONObject();
    
    cellJson.setBoolean("IsBomb", _isBomb);
    cellJson.setBoolean("IsFlaged", _flaged);
    cellJson.setInt("Num", _num);
    cellJson.setBoolean("IsEnabled", isEnabled());
    
    return cellJson;
  }
}
class Text extends GameObject {  
  private String _text;
  private int _textColor;
  private float _textSize;
  private int _textAlign = CENTER;
  
  
  public Text() {
   this(0, 0, ""); 
  }
  
  public Text(float x, float y, String text) {
    super(x, y);
   _text = text;
   _textSize = 20;
  }
  
  public void setColor(int textColor) {
   _textColor = textColor; 
  }
  
  public void setText(String text) {
    _text = text; 
  }
  
  public void setTextSize(float textSize) {
    _textSize = textSize; 
  }
  
  public void setAlign(int align) {
    if (align != LEFT && align != RIGHT && align != CENTER) return;
    _textAlign = align;
  }
  
  public void draw(PGraphics drawTarget) {
    drawTarget.pushMatrix();
    drawTarget.pushStyle();
    
    drawTarget.textSize(_textSize);    
    drawTarget.fill(_textColor);
    drawTarget.textAlign(_textAlign, CENTER);
    
    PVector pos = getPosition();
    drawTarget.text(_text, pos.x, pos.y);
    
    drawTarget.popMatrix();
    drawTarget.popStyle();
  }
}
public class TextButton extends Button {
  private Text _text;
  
  public TextButton(String text, float x, float y, float w, float h) {
   super(x, y, w, h);
   _text = new Text(x, y, text);
   _text.setColor(color(0));
  }
  
  public void draw(PGraphics drawTarget) {
    super.draw(drawTarget);
    
    drawTarget.pushMatrix();
    drawTarget.pushStyle();
    
    _text.draw(drawTarget);
    
    drawTarget.popStyle();
    drawTarget.popMatrix();
  }
  
  public void setText(String text) {
    _text.setText(text);
  }
  
  public void setTextColor(int textColor) {
    _text.setColor(textColor);
  }
  
  public void setPosition(float x, float y) {
    this.setPosition(new PVector(x, y)); 
  }
  
  public void setPosition(PVector pos) {
    super.setPosition(pos);
    _text.setPosition(pos);
  }
}
public class Tuple2<K, V> {

    private K first;
    private V second;
  
    public Tuple2(K first, V second){
        this.first = first;
        this.second = second;
    }

    public K getFirst() {
      return first;
    }
    
    public V getSecond() {
      return second;
    }
}


